import { ScheduleValueError } from './errors.mjs';

const INVALID_DAILY_TIME_FORMAT =
  'Invalid time format for a daily job (valid format is HH:MM(:SS)?)';
const INVALID_HOURS =
  'Invalid number of hours ({} is not between 0 and 23)';
const WEEKLY_TIME_PATTERN = /^\d{2}:[0-5]\d(?::[0-5]\d)?$/;

function validateWeeklyTime(timeText) {
  if (!WEEKLY_TIME_PATTERN.test(timeText)) {
    throw new ScheduleValueError(INVALID_DAILY_TIME_FORMAT, 514);
  }

  const hours = Number(timeText.slice(0, 2));
  if (hours < 0 || hours > 23) {
    throw new ScheduleValueError(INVALID_HOURS, 547);
  }
}

export class Job {
  constructor(interval = 1) {
    this.interval = interval;
    this.unit = 'days';
    this.startDay = null;
    this.jobFunc = null;
    this.jobArgs = [];
    this.jobKwargs = {};
    this.atTime = null;
  }

  get monday() {
    this.unit = 'weeks';
    this.startDay = 'monday';
    return this;
  }

  at(timeText) {
    validateWeeklyTime(timeText);
    this.atTime = timeText;
    return this;
  }

  toString() {
    return `Job(interval=${this.interval}, unit=${this.unit}, do=None, args=(), kwargs={})`;
  }
}

export function every(interval = 1) {
  return new Job(interval);
}

