const OPTION_ORDER = ['a', 'b', 'c'];

function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C\n`;
}

function formatHelp(programName) {
  return [
    `usage: ${programName} [-h] --a A --b B --c C`,
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
    '',
  ].join('\n');
}

function formatError(programName, message) {
  return `${formatUsage(programName)}${programName}: error: ${message}\n`;
}

function isOptionLike(token) {
  return token.length > 1 && token.startsWith('-');
}

function isSupportedOption(token) {
  return token === '--a' || token === '--b' || token === '--c';
}

function extractInlineOption(token) {
  if (!token.startsWith('--')) {
    return null;
  }

  const separatorIndex = token.indexOf('=');
  if (separatorIndex === -1) {
    return null;
  }

  const option = token.slice(0, separatorIndex);
  if (!isSupportedOption(option)) {
    return null;
  }

  return {
    key: option.slice(2),
    value: token.slice(separatorIndex + 1),
  };
}

function collectMissing(values) {
  return OPTION_ORDER.filter((key) => values[key] === undefined).map((key) => `--${key}`);
}

export function parseTest4Arguments(argv, programName) {
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        text: formatHelp(programName),
      };
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    const inline = extractInlineOption(token);
    if (inline !== null) {
      values[inline.key] = inline.value;
      continue;
    }

    if (isSupportedOption(token)) {
      const next = argv[index + 1];
      if (next === undefined || next === '--' || isOptionLike(next)) {
        return {
          kind: 'error',
          code: 2,
          text: formatError(programName, `argument ${token}: expected one argument`),
        };
      }

      values[token.slice(2)] = next;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = collectMissing(values);
  if (missing.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: formatError(
        programName,
        `the following arguments are required: ${missing.join(', ')}`,
      ),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: formatError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

