import { parseTest4Arguments } from './lib/cli/test4-arguments.mjs';
import { getProgramName } from './lib/runtime/program-name.mjs';
import { formatScheduleTraceback } from './lib/runtime/schedule-traceback.mjs';
import { every, ScheduleValueError } from './lib/schedule/index.mjs';

function main(argv) {
  const programName = getProgramName(argv);
  const parsed = parseTest4Arguments(argv.slice(2), programName);

  if (parsed.kind === 'help') {
    process.stdout.write(parsed.text);
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(parsed.text);
    return parsed.code;
  }

  try {
    const job = every().monday.at(parsed.values.a);
    console.log(job.toString());
    return 0;
  } catch (error) {
    if (error instanceof ScheduleValueError) {
      process.stderr.write(formatScheduleTraceback(error));
      return 1;
    }

    throw error;
  }
}

process.exit(main(process.argv));

